void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Нормализируем координаты
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // для правильного соотношения сторон

    // Параметры для групп обоев
    float pi = 3.141592653589793;
    float angle = pi / 3.0; // 60 градусов для тригонометрии обоев

    // Генерируем параметры симметрии, используя вращения и зеркальные отражения
    mat2 rotation60 = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv = uv * rotation60;
    uv = abs(uv);

    // Используем мод для повторяющегося узора
    uv = mod(uv, 2.0) - 1.0;
    uv = abs(uv);

    // Цветовая палитра с использованием длины и времени
    vec3 color = 0.5 + 0.5 * cos(iTime + vec3(0.0, 1.5, 3.0) + length(uv) * 6.28318);

    // Выводим цвет на экран
    fragColor = vec4(color, 1.0);
}
